//! Finite observer-return proof exchange and bounded refusal diagnostics.
use super::*;

/// Replay the same public proof after a lost response. No new Boot or signature
/// is generated by retries; Root deduplicates the exact bounded request.
pub(super) fn exchange_until(
    peer: &str,
    request: &serde_json::Value,
    deadline: Instant,
) -> Result<Vec<u8>> {
    let request = serde_json::to_vec(request)?;
    let (status, bytes) = transport(peer, "POST", "/body/join", &request, deadline)?;
    if status != 202 {
        return Err(format!(
            "return submission HTTP {status} ({}); retained request can be retried",
            refusal_reason(&bytes)
        )
        .into());
    }
    let ticket: Ticket = serde_json::from_slice(&bytes)?;
    if ticket.schema != "conduit.environment/body-join-queued@1" || ticket.ticket == 0 {
        return Err("return queue receipt differs".into());
    }
    loop {
        let (status, bytes) = transport(
            peer,
            "GET",
            &format!("/body/join/result?id={}", ticket.ticket),
            &[],
            deadline,
        )?;
        if status == 200 {
            return Ok(bytes);
        }
        if status != 202 || Instant::now() >= deadline {
            return Err(format!(
                "return receipt HTTP {status} ({}); retained request can be retried",
                refusal_reason(&bytes)
            )
            .into());
        }
        let pending: Ticket = serde_json::from_slice(&bytes)?;
        if pending.schema != ticket.schema || pending.ticket != ticket.ticket {
            return Err("return ticket differs".into());
        }
        std::thread::sleep(Duration::from_millis(250));
    }
}

fn transport(
    peer: &str,
    method: &str,
    path: &str,
    body: &[u8],
    deadline: Instant,
) -> Result<(u16, Vec<u8>)> {
    use std::net::ToSocketAddrs;
    // Resolution remains synchronous; every socket attempt consumes the same
    // caller deadline rather than manufacturing another three-second window.
    let address = peer
        .to_socket_addrs()?
        .find(|address| address.is_ipv4())
        .ok_or("observer return has no IPv4 route")?;
    retry_transport(
        || {
            crate::body_join::http::http_resolved_until(
                crate::body_join::http::Request {
                    peer,
                    method,
                    path,
                    body,
                    content_type: "application/json",
                },
                address,
                deadline,
            )
        },
        || Instant::now() >= deadline,
        || {
            if let Some(remaining) = deadline.checked_duration_since(Instant::now()) {
                std::thread::sleep(remaining.min(Duration::from_millis(50)));
            }
        },
    )
}
fn retry_transport<T>(
    mut request: impl FnMut() -> Result<T>,
    mut expired: impl FnMut() -> bool,
    mut pause: impl FnMut(),
) -> Result<T> {
    for _ in 0..24 {
        if expired() {
            return Err("return HTTP absolute deadline".into());
        }
        match request() {
            Ok(value) => {
                if expired() {
                    return Err("return HTTP absolute deadline".into());
                }
                return Ok(value);
            }
            Err(error) => {
                use std::io::ErrorKind;
                let retry = error.downcast_ref::<std::io::Error>().is_some_and(|error| {
                    matches!(
                        error.kind(),
                        ErrorKind::ConnectionRefused
                            | ErrorKind::ConnectionReset
                            | ErrorKind::ConnectionAborted
                            | ErrorKind::TimedOut
                            | ErrorKind::WouldBlock
                            | ErrorKind::Interrupted
                            | ErrorKind::UnexpectedEof
                    )
                });
                if !retry {
                    return Err(error);
                }
                pause();
            }
        }
    }
    Err("return HTTP transport retry bound".into())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn a_successful_transport_reply_after_the_deadline_is_not_adopted() {
        let expired = std::cell::Cell::new(false);
        let result = retry_transport(
            || {
                expired.set(true);
                Ok((200, vec![7]))
            },
            || expired.get(),
            || panic!("late success cannot retry"),
        );
        assert!(result
            .unwrap_err()
            .to_string()
            .contains("absolute deadline"));
    }
    #[test]
    fn transient_failures_retry_the_same_exchange_with_one_deadline() {
        use std::{
            cell::Cell,
            io::{Error, ErrorKind},
        };
        let attempts = Cell::new(0);
        let elapsed = Cell::new(0);
        let immutable_proof = vec![9; 40];
        let response = retry_transport(
            || {
                attempts.set(attempts.get() + 1);
                assert_eq!(immutable_proof, vec![9; 40]);
                if attempts.get() < 3 {
                    Err(Error::from(ErrorKind::ConnectionRefused).into())
                } else {
                    Ok((202, vec![7]))
                }
            },
            || elapsed.get() >= 100,
            || elapsed.set(elapsed.get() + 25),
        )
        .unwrap();
        assert_eq!(response, (202, vec![7]));
        assert_eq!(attempts.get(), 3);
        attempts.set(0);
        elapsed.set(0);
        let expired = retry_transport::<()>(
            || {
                attempts.set(attempts.get() + 1);
                Err(Error::from(ErrorKind::WouldBlock).into())
            },
            || elapsed.get() >= 100,
            || elapsed.set(elapsed.get() + 50),
        )
        .unwrap_err();
        assert!(expired.to_string().contains("absolute deadline"));
        assert_eq!(attempts.get(), 2);
        assert!(retry_transport::<()>(
            || Err(Error::from(ErrorKind::InvalidData).into()),
            || false,
            || panic!("permanent error retried"),
        )
        .is_err());
        assert_eq!(
            retry_transport(
                || Ok((409, vec![1])),
                || false,
                || panic!("refusal retried")
            )
            .unwrap(),
            (409, vec![1])
        );
    }
    #[test]
    fn refusal_reason_is_bounded_and_old_responses_remain_supported() {
        assert_eq!(refusal_reason(br#"{"schema":"conduit.environment/body-join-refused@1","ticket":1,"reason":"body-return-challenge"}"#), "body-return-challenge");
        for bytes in [
            br#"{"schema":"conduit.environment/body-join-refused@1","ticket":1}"#.as_slice(),
            br#"{"schema":"wrong","reason":"secret"}"#,
            br#"{"schema":"conduit.environment/body-join-refused@1","reason":"line\nsecret"}"#,
            b"not json",
        ] {
            assert_eq!(refusal_reason(bytes), "unspecified");
        }
    }
}
